const ran = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
const errText = (e) => {
  if (!e) return '';
  if (typeof e === 'string') return e;
  return e.message || e.description || JSON.stringify(e);
};
const execUrl = 'https://retailguardprojtest.app.n8n.cloud/workflow/' + $workflow.id + '/executions/' + $execution.id;
const runAt = $now.setZone('Asia/Kolkata').toFormat('yyyy-LL-dd HH:mm:ss');

// Early failure: a data step failed and sent its error here, so the UI check never ran
if (!ran('Verify Browserless UI')) {
  const steps = [
    ['HTTP Request', 'Download cases spreadsheet from GitHub'],
    ['Extract from File1', 'Read spreadsheet rows'],
    ['Code in JavaScript', 'Calculate variance and alerts'],
    ['Summary Node', 'Build summary']
  ];
  let failed = steps[0];
  for (const s of steps) { if (ran(s[0])) failed = s; }
  const first = $input.first();
  const err = errText(first && first.json && first.json.error) || 'Unknown error';
  const html =
    '<h2 style="color:#cf222e">RetailGuard E2E run: FAILED</h2>' +
    '<p>Run time (IST): ' + runAt + '<br>Execution: <a href="' + execUrl + '">' + execUrl + '</a></p>' +
    '<p><b>Failed step:</b> ' + failed[1] + ' (node "' + failed[0] + '")</p>' +
    '<p><b>Error:</b> ' + String(err).replace(/</g, '&lt;') + '</p>' +
    '<p>Later steps (send to Lovable, Browserless UI check) did not run. Error details are attached.</p>';
  const report = 'RetailGuard E2E run: FAILED\nRun time (IST): ' + runAt + '\nExecution: ' + execUrl +
    '\nFailed step: ' + failed[1] + ' (node ' + failed[0] + ')\nError: ' + err + '\n';
  return [{
    json: { status: 'FAILED', failedStep: failed[0], error: err, subject: 'RetailGuard E2E run FAILED - ' + runAt, html, executionUrl: execUrl },
    binary: { data: { data: Buffer.from(report).toString('base64'), mimeType: 'text/plain', fileName: 'retailguard-error-report.txt' } }
  }];
}

const shot = $input.first();
// Read output 0 (success): this node also links here via its error output, which is empty on a good run
let summary = {};
try { summary = ($('Summary Node').first(0) || {}).json || {}; } catch (e) { summary = {}; }

let lovable = {};
try { lovable = $('Send Data to Lovable').first().json || {}; } catch (e) { lovable = { error: 'Step did not run' }; }

const lovableOk = !lovable.error;
const screenshot = shot.binary && shot.binary.data;
const uiOk = !shot.json.error && !!screenshot;
const status = lovableOk && uiOk ? 'SUCCESS' : 'FAILED';

const row = (label, value) => '<tr><td style="padding:4px 12px;border:1px solid #ddd"><b>' + label + '</b></td><td style="padding:4px 12px;border:1px solid #ddd">' + value + '</td></tr>';
const stepLine = (ok, err) => ok ? 'Passed' : 'Failed: ' + errText(err);

const html =
  '<h2 style="color:' + (status === 'SUCCESS' ? '#1a7f37' : '#cf222e') + '">RetailGuard E2E run: ' + status + '</h2>' +
  '<p>Run time (IST): ' + runAt + '<br>Execution: <a href="' + execUrl + '">' + execUrl + '</a></p>' +
  '<h3>Step results</h3><table style="border-collapse:collapse">' +
  row('Send data to Lovable', stepLine(lovableOk, lovable.error)) +
  row('Browserless UI check', stepLine(uiOk, shot.json.error || (screenshot ? '' : 'No screenshot returned'))) +
  '</table>' +
  '<h3>Inventory summary</h3><table style="border-collapse:collapse">' +
  row('Total records', summary.totalRecords ?? 'n/a') +
  row('Inventory alerts', summary.inventoryAlerts ?? 'n/a') +
  row('Discount alerts', summary.discountAlerts ?? 'n/a') +
  row('Returns alerts', summary.returnsAlerts ?? 'n/a') +
  row('Records requiring review', summary.recordsRequiringReview ?? 'n/a') +
  row('Records with validation issues', summary.recordsWithValidationIssues ?? 'n/a') +
  '</table>' +
  '<p>' + (uiOk ? 'Screenshot of the UI is attached.' : 'Error details are attached.') + '</p>';

let binary;
if (uiOk) {
  binary = { data: { ...screenshot, fileName: screenshot.fileName || 'retailguard-ui-screenshot.png' } };
} else {
  const report = 'RetailGuard E2E run: ' + status + '\nRun time (IST): ' + runAt + '\nExecution: ' + execUrl +
    '\n\nSend data to Lovable: ' + stepLine(lovableOk, lovable.error) +
    '\nBrowserless UI check: ' + stepLine(uiOk, shot.json.error || 'No screenshot returned') + '\n';
  binary = { data: { data: Buffer.from(report).toString('base64'), mimeType: 'text/plain', fileName: 'retailguard-error-report.txt' } };
}

return [{
  json: { status, subject: 'RetailGuard E2E run ' + status + ' - ' + runAt, html, executionUrl: execUrl },
  binary
}];

const items = $input.all();
const seenCaseIds = new Set();

const num = (value) => {
  if (value === null || value === undefined || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
};

return items.map((item) => {
  const r = item.json;
  const caseId = r["Case ID"];
  const duplicateCaseId = caseId ? seenCaseIds.has(caseId) : false;
  if (caseId) seenCaseIds.add(caseId);

  const opening = num(r["Synthetic Opening Stock"]);
  const received = num(r["Synthetic Purchases Received"]);
  const customerReturns = num(r["Synthetic Customer Returns Restocked"]);
  const sold = num(r["Source Units Sold"]);
  const supplierReturns = num(r["Synthetic Supplier Returns"]);
  const actualClosing = num(r["Synthetic Actual Closing Stock"]);

  const required = [
    opening, received, customerReturns, sold,
    supplierReturns, actualClosing
  ];

  const missingStockInputs = required.some(v => v === null);

  let expectedClosing = null;
  let variance = null;

  if (!missingStockInputs) {
    expectedClosing =
      opening + received + customerReturns - sold - supplierReturns;
    variance = actualClosing - expectedClosing;
  }

  const discount = num(r["Source Discount (%)"]);
  const inventoryAlert =
    variance !== null && Math.abs(variance) >= 5;
  const discountAlert = discount !== null && discount >= 20;
  const returnsAlert =
    customerReturns !== null && customerReturns >= 4;

  const alerts = [];
  if (inventoryAlert) alerts.push("INVENTORY_VARIANCE");
  if (discountAlert) alerts.push("HIGH_DISCOUNT");
  if (returnsAlert) alerts.push("HIGH_CUSTOMER_RETURNS");

  const missingIdentity =
    !caseId || !r["Date"] || !r["Store ID"] || !r["Product ID"];

  const validationIssues = [];
  if (missingIdentity) validationIssues.push("Missing case/date/store/product identity");
  if (duplicateCaseId) validationIssues.push("Duplicate Case ID");
  if (missingStockInputs) validationIssues.push("Inventory variance unavailable: required stock inputs missing");

  let nextCheck = "Review the source record and confirm the transaction details.";
  if (inventoryAlert) {
    nextCheck = "Verify physical stock count, goods received, sales, returns and supplier-return records.";
  } else if (discountAlert) {
    nextCheck = "Check discount authorisation and the promotion or transaction record.";
  } else if (returnsAlert) {
    nextCheck = "Verify returned units and confirm that restocked units were physically returned to inventory.";
  }

  const summary = alerts.length
    ? "Review requested: " + alerts.join(", ") + ". This is a rule-based flag, not proof of fraud."
    : "No configured alert rule was triggered. This does not guarantee the record is error-free.";

  return {
    json: {
      ...r,
      "Data Status": validationIssues.length ? "REVIEW_DATA" : "VALIDATED_FOR_RULES",
      "Validation Issues": validationIssues.join("; "),
      "Expected Closing Stock (Calculated)": expectedClosing,
      "Inventory Variance (Calculated)": variance,
      "Inventory Alert": inventoryAlert,
      "Discount Alert": discountAlert,
      "Returns Alert": returnsAlert,
      "Alert Types": alerts.join(", "),
      "Review Priority": alerts.length ? "Review Required" : "No Rule Triggered",
      "Investigation Summary": summary,
      "Recommended Next Check": nextCheck,
      "Data Provenance": "Source fields retained; synthetic movement fields are demonstration data"
    }
  };
});

const rows = $input.all().map(item => item.json);

const count = (field) =>
  rows.filter(row => row[field] === true).length;

const pick = (r, keys) => {
  for (const k of keys) {
    if (r[k] !== undefined && r[k] !== null && r[k] !== '') return r[k];
  }
  return null;
};

const cases = rows.map(r => ({
  ...r,
  "Case ID": pick(r, ["Case ID", "Case_ID", "case_id", "record_id"]),
  "Store ID": pick(r, ["Store ID", "store_id"]),
  "Product ID": pick(r, ["Product ID", "product_id"]),
  "Date": pick(r, ["Date", "period_end", "date"])
}));

return [{
  json: {
    totalRecords: rows.length,
    inventoryAlerts: count("Inventory Alert"),
    discountAlerts: count("Discount Alert"),
    returnsAlerts: count("Returns Alert"),
    recordsRequiringReview: rows.filter(
      row => row["Review Priority"] === "Review Required"
    ).length,
    recordsWithValidationIssues: rows.filter(
      row => row["Validation Issues"]
    ).length,
    cases
  }
}];

